using System.Collections;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Combat
{
public sealed class LaneWaveSpawner:MonoBehaviour
{
[SerializeField]private float firstWaveDelay=4,waveInterval=25,unitSpacing=1.1f;[SerializeField]private int unitsPerWave=3;[SerializeField]private float siegeMechTime=360f,siegeWarningLead=10f;private static bool siegeMechsSpawned;public static event System.Action<float> SiegeWaveWarning;public static event System.Action SiegeWaveSpawned;private static readonly float[] LaneZ={16,-16};[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]private static void ResetSiegeState(){siegeMechsSpawned=false;}private IEnumerator Start(){if(!siegeMechsSpawned)StartCoroutine(SiegeMechRoutine());yield return WaitGameSeconds(firstWaveDelay);while(true){SpawnAllLanes();yield return WaitGameSeconds(waveInterval);}}private IEnumerator SiegeMechRoutine(){yield return WaitGameSeconds(Mathf.Max(0f,siegeMechTime-siegeWarningLead));if(MatchEnded())yield break;SiegeWaveWarning?.Invoke(siegeWarningLead);yield return WaitGameSeconds(siegeWarningLead);if(siegeMechsSpawned||MatchEnded())yield break;siegeMechsSpawned=true;foreach(float laneZ in LaneZ){CreateSiegeMech(0,laneZ);CreateSiegeMech(1,laneZ);}SiegeWaveSpawned?.Invoke();}private static bool MatchEnded(){Alterverse.Match.DimensionsFront front=FindAnyObjectByType<Alterverse.Match.DimensionsFront>();return front!=null&&front.HasEnded;}private static IEnumerator WaitGameSeconds(float seconds){float elapsed=0f;while(elapsed<seconds){if(Time.timeScale>0f)elapsed+=Time.deltaTime;yield return null;}}private void SpawnAllLanes(){if(Time.timeScale<=0f||MatchEnded())return;foreach(float laneZ in LaneZ){SpawnWave(0,laneZ);SpawnWave(1,laneZ);}}
private void SpawnWave(int team,float laneZ){float startX=team==0?-30:30,destinationX=team==0?31:-31,direction=team==0?-1:1;for(int i=0;i<unitsPerWave;i++){Vector3 spawn=new(startX+direction*i*unitSpacing,.55f,laneZ);CreateMinion(team,spawn,new Vector3(destinationX,.55f,laneZ),i);}}
private static void CreateMinion(int team,Vector3 spawn,Vector3 destination,int index){Color energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy,dark=team==0?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;GameObject minion=GameObject.CreatePrimitive(PrimitiveType.Capsule);minion.name=team==0?$"DF_ZeroMinion_{index}":$"DF_LumenMinion_{index}";minion.transform.position=spawn;GameObject world=GameObject.Find("DF_MatchWorld");if(world!=null)minion.transform.SetParent(world.transform,true);minion.transform.localScale=new Vector3(.5f,.5f,.5f);Renderer renderer=minion.GetComponent<Renderer>();if(renderer!=null){renderer.material.color=dark;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;}Health health=minion.AddComponent<Health>();health.Configure(70,true);minion.AddComponent<LaneMinion>().Initialize(team,destination);CreatePart(minion.transform,"DF_Visor",PrimitiveType.Cube,new Vector3(0,.42f,.42f),new Vector3(.62f,.12f,.10f),energy);CreatePart(minion.transform,"DF_Shoulder",PrimitiveType.Cube,new Vector3(0,.12f,0),new Vector3(.92f,.14f,.5f),energy);CreatePart(minion.transform,"DF_BackPlate",PrimitiveType.Cube,new Vector3(0,.1f,-.34f),new Vector3(.58f,.3f,.12f),dark);CreatePart(minion.transform,"DF_TeamFin",PrimitiveType.Cube,new Vector3(0,.72f,-.05f),new Vector3(.10f,.42f,.28f),energy);Object.Destroy(minion,75);}
private static void CreateSiegeMech(int team,float laneZ){float startX=team==0?-30:30,destinationX=team==0?31:-31;Color energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy,dark=team==0?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;GameObject mech=GameObject.CreatePrimitive(PrimitiveType.Capsule);mech.name=team==0?"DF_ZeroSiegeMech":"DF_LumenSiegeMech";mech.transform.position=new Vector3(startX,.85f,laneZ);GameObject world=GameObject.Find("DF_MatchWorld");if(world!=null)mech.transform.SetParent(world.transform,true);mech.transform.localScale=new Vector3(1.05f,1.05f,1.05f);Renderer renderer=mech.GetComponent<Renderer>();if(renderer!=null)renderer.material.color=dark;Health hp=mech.AddComponent<Health>();hp.Configure(420,true);LaneMinion unit=mech.AddComponent<LaneMinion>();unit.Initialize(team,new Vector3(destinationX,.85f,laneZ));unit.ConfigureFrontInfluence(.30f);unit.ConfigureSiegeRole();unit.ConfigureCombat(2.15f,8.2f,2.15f,10.5f,1.25f,1.65f);CreatePart(mech.transform,"DF_MechChest",PrimitiveType.Cube,new Vector3(0,.2f,0),new Vector3(1.25f,.65f,.8f),dark);CreatePart(mech.transform,"DF_MechCore",PrimitiveType.Cube,new Vector3(0,.22f,.43f),new Vector3(.48f,.3f,.08f),energy);CreatePart(mech.transform,"DF_MechShoulderL",PrimitiveType.Cube,new Vector3(-.72f,.28f,0),new Vector3(.34f,.5f,.62f),energy);CreatePart(mech.transform,"DF_MechShoulderR",PrimitiveType.Cube,new Vector3(.72f,.28f,0),new Vector3(.34f,.5f,.62f),energy);CreatePart(mech.transform,"DF_MechRam",PrimitiveType.Cube,new Vector3(0,-.15f,.72f),new Vector3(.72f,.28f,.62f),energy);CreatePart(mech.transform,"DF_MechCrown",PrimitiveType.Cube,new Vector3(0,.92f,.05f),new Vector3(.28f,.38f,.52f),energy);Object.Destroy(mech,100);}
private static void CreatePart(Transform parent,string name,PrimitiveType type,Vector3 pos,Vector3 scale,Color color){GameObject p=GameObject.CreatePrimitive(type);p.name=name;p.transform.SetParent(parent,false);p.transform.localPosition=pos;p.transform.localScale=scale;Collider c=p.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=p.GetComponent<Renderer>();if(r!=null)r.material.color=color;}
}
}
